/// Accurate, simple, and learner-friendly Kannada translations for 200 Advanced sentences (a001 - a200)
const Map<String, String> advancedKannada = {
  'a001': 'ಜ್ಞಾನಮೀಮಾಂಸೆಯ ವಿಚಾರಣೆಯು ಜ್ಞಾನದ ಮೂಲಭೂತ ಊಹೆಗಳನ್ನು ಸೂಕ್ಷ್ಮವಾಗಿ ಪರಿಶೀಲಿಸಲು ವಿದ್ವಾಂಸರನ್ನು ಪ್ರೇರೇಪಿಸುತ್ತದೆ.',
  'a002': 'ಪ್ರಾಧ್ಯಾಪಕರು ಸಾಹಿತ್ಯಿಕ ಸಂಕೇತಶಾಸ್ತ್ರದ ಬಗ್ಗೆ ಆಳವಾದ ಮತ್ತು ಸೂಕ್ಷ್ಮವಾದ ವಿಮರ್ಶೆಯನ್ನು ಮಂಡಿಸಿದರು.',
  'a003': 'ಮಾನವ ಪ್ರಜ್ಞೆಯು ಸಂಪೂರ್ಣವಾಗಿ ಕೇವಲ ಭೌತಿಕ ವಿವರಣೆಗಳಿಗೆ ನಿಲುಕದ ಒಂದು ಅದ್ಭುತ ವಿದ್ಯಮಾನವಾಗಿದೆ.',
  'a004': 'ಅಸ್ತಿತ್ವವಾದಿ ತತ್ತ್ವಶಾಸ್ತ್ರವು ಮಾನವರು ಈ ಜಗತ್ತಿನಲ್ಲಿ ತಮ್ಮದೇ ಆದ ನಿಜವಾದ ಅರ್ಥವನ್ನು ಕಂಡುಕೊಳ್ಳಬೇಕೆಂದು ಪ್ರತಿಪಾದಿಸುತ್ತದೆ.',
  'a005': 'ಈ ಸಂಶೋಧನಾ ಪ್ರಬಂಧವು ಗುಣಾತ್ಮಕ ಮಾನವಶಾಸ್ತ್ರ ಮತ್ತು ಪರಿಮಾಣಾತ್ಮಕ ಆರ್ಥಿಕ ಮಾದರಿಗಳನ್ನು ಸಮಗ್ರವಾಗಿ ಸಂಯೋಜಿಸುತ್ತದೆ.',
  'a006': 'ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಪ್ರಮುಖ ನಂಬಿಕೆಗಳು ವಾಸ್ತವಕ್ಕೆ ವಿರುದ್ಧವಾದಾಗ ಮಾನಸಿಕ ಗೊಂದಲ ಅಥವಾ ಅಸಂಗತತೆ ಉಂಟಾಗುತ್ತದೆ.',
  'a007': 'ಈ ವಿಚಾರ ಸಂಕಿರಣವು ಆಧುನಿಕ ವೈದ್ಯಕೀಯ ಸಂಶೋಧನೆಯಲ್ಲಿ ಜೀನ್ ಎಡಿಟಿಂಗ್ ತಂತ್ರಜ್ಞಾನದ ನೈತಿಕ ಪರಿಣಾಮಗಳನ್ನು ಅನ್ವೇಷಿಸಿತು.',
  'a008': 'ಐತಿಹಾಸಿಕ ತಾರತಮ್ಯದಿಂದ ಮುಂದುವರಿದ ವ್ಯವಸ್ಥಿತ ಅಸಮಾನತೆಗಳನ್ನು ಎತ್ತಿ ತೋರಿಸುವ ಭಾವನಾತ್ಮಕ ವಿಮರ್ಶೆಯನ್ನು ಅವರು ನೀಡಿದರು.',
  'a009': 'ಸಂಶೋಧಕರು ತಮ್ಮ ಪ್ರಯೋಗಗಳ ಮಿತಿಗಳನ್ನು ಮುಕ್ತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಬೇಕೆಂದು ಬೌದ್ಧಿಕ ಪ್ರಾಮಾಣಿಕತೆ ಬಯಸುತ್ತದೆ.',
  'a010': 'ಸಾಕ್ರಟೀಸ್‌ನ ಸಂವಾದ ವಿಧಾನವು ನಿರಂತರ ಪ್ರಶ್ನೋತ್ತರಗಳ ಮೂಲಕ ಮೂಢನಂಬಿಕೆಗಳನ್ನು ಮತ್ತು ಪೂರ್ವಾಗ್ರಹಗಳನ್ನು ಹೋಗಲಾಡಿಸುತ್ತದೆ.',
  'a011': 'ಐತಿಹಾಸಿಕ ಘಟನೆಗಳು ಸಂಪ್ರದಾಯ ಮತ್ತು ಸುಧಾರಣೆಗಳ ನಡುವಿನ ನಿರಂತರ ಸಂಘರ್ಷವನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ವಿವರಿಸುತ್ತವೆ.',
  'a012': 'ಉತ್ತರ-ಆಧುನಿಕ ವಾಸ್ತುಶಿಲ್ಪವು ಐತಿಹಾಸಿಕ ಅಲಂಕಾರಗಳನ್ನು ಅಳವಡಿಸಿಕೊಳ್ಳುವ ಮೂಲಕ ಆಧುನಿಕ ಕಟ್ಟುಪಾಡುಗಳನ್ನು ಮೀರುತ್ತದೆ.',
  'a013': 'ಆಕೆಯ ಪ್ರಬಂಧವು ಹಿಂದುಳಿದ ಸಮುದಾಯಗಳಲ್ಲಿ ಭಾಷಾ ಉಪಭಾಷೆಗಳ ಉಳಿವಿಗೆ ಕಾರಣವಾಗುವ ಅಂಶಗಳನ್ನು ತನಿಖೆ ಮಾಡುತ್ತದೆ.',
  'a014': 'ಯಾವುದೇ ಕ್ರಿಯೆಯ ನೈತಿಕ ಮೌಲ್ಯವನ್ನು ಅದರ ಅಂತಿಮ ಪರಿಣಾಮಗಳ ಆಧಾರದ ಮೇಲೆ ಅಳೆಯಲಾಗುತ್ತದೆ ಎಂದು ಪ್ರಯೋಜನವಾದ ಹೇಳುತ್ತದೆ.',
  'a015': 'ಭಾಷಾ ಮಿತಿಗಳು ಮಾನವನ ಆಲೋಚನಾ ವ್ಯಾಪ್ತಿಯನ್ನು ನಿರ್ಧರಿಸುತ್ತವೆ ಎಂದು ತತ್ವಜ್ಞಾನಿ ವಾದಿಸಿದರು.',
  'a016': 'ವಿಶ್ವವು ಒಂದು ಅಂತರ್ಗತ ಉದ್ದೇಶ ಮತ್ತು ನಿರ್ದೇಶನವನ್ನು ಹೊಂದಿದೆ ಎಂದು ಉದ್ದೇಶಶಾಸ್ತ್ರೀಯ ದೃಷ್ಟಿಕೋನವು ನಂಬುತ್ತದೆ.',
  'a017': 'ದಾಖಲೆಗಳ ಶೋಧನೆಯು ಕೈಗಾರಿಕಾ ಕ್ರಾಂತಿಯ ಬಗೆಗಿನ ವಿದ್ವಾಂಸರ ವ್ಯಾಖ್ಯಾನಗಳಲ್ಲಿ ಆಮೂಲಾಗ್ರ ಬದಲಾವಣೆಯನ್ನು ತಂದಿತು.',
  'a018': 'ವಿರೋಧಿ ನಿಯೋಗಗಳು ನಿಖರವಾದ ಐತಿಹಾಸಿಕ ಪುರಾವೆಗಳನ್ನು ಮಂಡಿಸಿದಾಗ ಪಾಂಡಿತ್ಯಪೂರ್ಣ ಚರ್ಚೆಯು ಕಳೆಗಟ್ಟಿತು.',
  'a019': 'ನಮ್ಮ ಗ್ರಹಿಕೆಯು ಬಾಹ್ಯ ನೈಜತೆಗೆ ನಿಖರವಾಗಿ ಹೊಂದಿಕೊಳ್ಳುತ್ತದೆಯೇ ಎಂದು ತಾತ್ವಿಕ ಸಂದೇಹವಾದವು ಪ್ರಶ್ನಿಸುತ್ತದೆ.',
  'a020': 'ನೈತಿಕ ತತ್ವಗಳು ಸಾರ್ವತ್ರಿಕ ನಿಯಮಗಳಲ್ಲ, ಬದಲಿಗೆ ಸಂಸ್ಕೃತಿಗೆ ತಕ್ಕಂತೆ ಬದಲಾಗುತ್ತವೆ ಎಂದು ನೈತಿಕ ಸಾಪೇಕ್ಷತಾವಾದ ವಾದಿಸುತ್ತದೆ.',
  'a021': 'ಆಡಳಿತ ಮತ್ತು ಷೇರು ಹಂಚಿಕೆಯ ಮೇಲಿನ ಸುದೀರ್ಘ ಭಿನ್ನಾಭಿಪ್ರಾಯಗಳಿಂದಾಗಿ ಕಂಪನಿಗಳ ವಿಲೀನವು ಅನಿರ್ದಿಷ್ಟವಾಗಿ ಸ್ಥಗಿತಗೊಂಡಿತು.',
  'a022': 'ಬಹುಪಕ್ಷೀಯ ಮಾತುಕತೆಗಳ ನಡುವೆ ಸೌಹಾರ್ದಯುತ ಒಮ್ಮತವನ್ನು ಮೂಡಿಸಲು ರಾಜತಾಂತ್ರಿಕರು ದಣಿವರಿಯದೆ ಶ್ರಮಿಸಿದರು.',
  'a023': 'ನಾಯಕತ್ವ ತಂಡಗಳಲ್ಲಿ ಮಾನಸಿಕ ಸುರಕ್ಷತೆಯನ್ನು ಬೆಳೆಸುವುದು ಹೊಸ ಆವಿಷ್ಕಾರವನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ ಮತ್ತು ತಪ್ಪುಗಳನ್ನು ತಡೆಯುತ್ತದೆ.',
  'a024': 'ಮುಂಬರುವ ಆರ್ಥಿಕ ಬಿಕ್ಕಟ್ಟನ್ನು ತಡೆದುಕೊಳ್ಳಲು ಮುಖ್ಯ ಹಣಕಾಸು ಅಧಿಕಾರಿಯು ಕಟ್ಟುನಿಟ್ಟಾದ ಮಿತವ್ಯಯ ಕ್ರಮಗಳನ್ನು ಜಾರಿಗೆ ತಂದರು.',
  'a025': 'ಗಡಿಯಾಚೆಗಿನ ಕಂಪನಿ ಖರೀದಿಗಳು ಸುಪ್ತ ನಿಯಂತ್ರಕ ಮತ್ತು ಆರ್ಥಿಕ ಹೊಣೆಗಾರಿಕೆಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸಲು ಸೂಕ್ತ ಪರಿಶೀಲನೆ ಬಯಸುತ್ತವೆ.',
  'a026': 'ಆಕೆಯು ಕಾರ್ಪೊರೇಟ್ ವಲಯದ ಕಠಿಣ ಪರಿಸ್ಥಿತಿಗಳನ್ನು ರಾಜತಾಂತ್ರಿಕ ಜಾಣ್ಮೆ ಮತ್ತು ದೃಢ ಸಂಕಲ್ಪದಿಂದ ನಿಭಾಯಿಸಿದಳು.',
  'a027': 'ಪ್ರಾದೇಶಿಕ ವ್ಯಾಪಾರ ಘಟಕಗಳಿಗೆ ಸ್ವಾಯತ್ತ ಅಧಿಕಾರ ನೀಡಲು ಸಂಸ್ಥೆಯು ವಿಕೇಂದ್ರೀಕೃತ ಆಡಳಿತ ರಚನೆಯನ್ನು ಸ್ಥಾಪಿಸಿತು.',
  'a028': 'ತೀವ್ರ ಮಾರುಕಟ್ಟೆ ಸ್ಪರ್ಧೆಯು ಟೆಲಿಕಾಂ ಸಂಸ್ಥೆಯನ್ನು ತನ್ನ ಸಾಂಪ್ರದಾಯಿಕ ವ್ಯಾಪಾರ ಮಾದರಿಯನ್ನು ಬದಲಾಯಿಸಲು ಒತ್ತಾಯಿಸಿತು.',
  'a029': 'ಷೇರುದಾರರು ಕಂಪನಿಯ ಪರಿಸರ ಮತ್ತು ಆಡಳಿತ ವರದಿಗಳನ್ನು ತೀವ್ರ ಪರಿಶೀಲನೆಗೆ ಒಳಪಡಿಸಿದರು.',
  'a030': 'ಕಾರ್ಯಾಚರಣೆಯ ವೆಚ್ಚವನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಪುನರ್ರಚನಾ ಉಪಕ್ರಮವು ಇಲಾಖೆಗಳ ವಿಲೀನವನ್ನು ಒಳಗೊಂಡಿತ್ತು.',
  'a031': 'ಅವನು ಸಮಗ್ರ ಆರೋಗ್ಯ ಮತ್ತು ವೃತ್ತಿ ಪರಿವರ್ತನಾ ಸೇವೆಗಳನ್ನು ಒಳಗೊಂಡ ಉತ್ತಮ ಪರಿಹಾರ ಪ್ಯಾಕೇಜ್ ಪಡೆದುಕೊಂಡನು.',
  'a032': 'ವಿವಿಧ ಆಸ್ತಿ ವರ್ಗಗಳಲ್ಲಿ ಕಾರ್ಯತಂತ್ರದ ಹೂಡಿಕೆ ಮಾಡುವುದು ಆರ್ಥಿಕ ಹಿಂಜರಿತದ ಅಪಾಯವನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.',
  'a033': 'ಸೈಬರ್ ದಾಳಿಗೆ ಒಗ್ಗಟ್ಟಿನ ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ರೂಪಿಸಲು ಕಾರ್ಯಕಾರಿ ಸಮಿತಿಯು ತುರ್ತು ಸಭೆಯನ್ನು ಕರೆಯಿತು.',
  'a034': 'ಆಕೆಯ ಸ್ಪಷ್ಟ ಮತ್ತು ಸಶಕ್ತ ಉತ್ತರವು ವಿರೋಧಿಗಳು ಹೊರಿಸಿದ ಪ್ರತಿಯೊಂದು ಆಧಾರರಹಿತ ಆರೋಪವನ್ನೂ ವ್ಯವಸ್ಥಿತವಾಗಿ ಹುಸಿಮಾಡಿತು.',
  'a035': 'ಕಿರಿಯ ಸಹೋದ್ಯೋಗಿಗಳೂ ಹೊಸ ಆಲೋಚನೆಗಳನ್ನು ಮಂಡಿಸಬಹುದಾದ ಸಮಾನತೆಯ ಸಂಸ್ಕೃತಿಯನ್ನು ಸಂಸ್ಥೆಯು ಬೆಳೆಸಿತು.',
  'a036:': 'ಸಂಸ್ಥೆಯ ದೀರ್ಘಾವಧಿಯ ಆರ್ಥಿಕ ಸ್ಥಿರತೆಗೆ ಆದ್ಯತೆ ನೀಡುವುದು ಕಾರ್ಪೊರೇಟ್ ಮಂಡಳಿಗಳ ಕಾನೂನಾತ್ಮಕ ಜವಾಬ್ದಾರಿಯಾಗಿದೆ.',
  'a036': 'ಸಂಸ್ಥೆಯ ದೀರ್ಘಾವಧಿಯ ಆರ್ಥಿಕ ಸ್ಥಿರತೆಗೆ ಆದ್ಯತೆ ನೀಡುವುದು ಕಾರ್ಪೊರೇಟ್ ಮಂಡಳಿಗಳ ಕಾನೂನಾತ್ಮಕ ಜವಾಬ್ದಾರಿಯಾಗಿದೆ.',
  'a037': 'ನಾಗರಿಕರ ಸಕ್ರಿಯ ಪಾಲ್ಗೊಳ್ಳುವಿಕೆಯು ನಗರ ವಲಯ ಸುಧಾರಣೆಗಳ ಸಮಯದಲ್ಲಿ ಉಂಟಾಗುವ ಸಂಘರ್ಷವನ್ನು ತಗ್ಗಿಸುತ್ತದೆ.',
  'a038': 'ಲಾಭದಾಯಕ ಕ್ಲೌಡ್ ತಂತ್ರಜ್ಞಾನದ ಮೇಲೆ ಗಮನಹರಿಸಲು ಸಂಸ್ಥೆಯು ನಷ್ಟದಲ್ಲಿದ್ದ ಚಿಲ್ಲರೆ ವ್ಯಾಪಾರಗಳನ್ನು ಮಾರಾಟ ಮಾಡಿತು.',
  'a039': 'ಸೂಕ್ಷ್ಮ ಮಾತುಕತೆಗಳ ಸಮಯದಲ್ಲಿ ಪ್ರಚೋದನಕಾರಿ ಭಾಷಣಕ್ಕಿಂತ ರಾಜತಾಂತ್ರಿಕ ಮೌನವೇ ಹೆಚ್ಚು ಪರಿಣಾಮಕಾರಿಯಾಗುತ್ತದೆ.',
  'a040': 'ಗ್ರಾಹಕರನ್ನು ಉಳಿಸಿಕೊಳ್ಳುವುದು ಮತ್ತು ಹೊಸ ಗ್ರಾಹಕರನ್ನು ಗಳಿಸುವುದರ ನಡುವಿನ ಸಮತೋಲನವೇ ಶಾಶ್ವತ ಲಾಭದ ಗುಟ್ಟು.',
  'a041': 'ಕ್ವಾಂಟಮ್ ಕಂಪ್ಯೂಟಿಂಗ್ ಪ್ರಸ್ತುತ ಎನ್‌ಕ್ರಿಪ್ಶನ್ ಪದ್ಧತಿಗಳನ್ನು ಮೀರಿಸುವ ಅಗಾಧ ಕಂಪ್ಯೂಟಿಂಗ್ ವೇಗವನ್ನು ನೀಡುತ್ತದೆ.',
  'a042': 'ಅಲ್ಗಾರಿದಮ್‌ಗಳಲ್ಲಿನ ಪೂರ್ವಾಗ್ರಹಗಳು ವ್ಯವಸ್ಥಿತ ತಾರತಮ್ಯವನ್ನು ಮುಂದುವರಿಸುವ ಅಪಾಯವನ್ನು ಹೊಂದಿರುತ್ತವೆ.',
  'a043': 'ಸ್ವಯಂಚಾಲಿತ ವಾಹನಗಳು ಲಿಡಾರ್, ರೇಡಾರ್ ಮತ್ತು ಕ್ಯಾಮೆರಾಗಳ ನೈಜ ಸಮಯದ ಸಂಯೋಜನೆಯ ಮೇಲೆ ಅವಲಂಬಿತವಾಗಿವೆ.',
  'a044': 'ವಿಕೇಂದ್ರೀಕೃತ ತಂತ್ರಜ್ಞಾನಕ್ಕೆ ಪರಿವರ್ತನೆಯಾಗುವುದು ಜಾಗತಿಕ ಸರಕು ಸಾಗಣೆಯಲ್ಲಿ ಅಭೂತಪೂರ್ವ ಪಾರದರ್ಶಕತೆಯನ್ನು ತರುತ್ತದೆ.',
  'a045': 'ಜೈವಿಕ ತಂತ್ರಜ್ಞಾನವು ಜೀವ ಉಳಿಸುವ ಔಷಧಿಗಳನ್ನು ಸಂಶ್ಲೇಷಿಸಲು ಕಸ್ಟಮೈಸ್ ಮಾಡಿದ ಸೂಕ್ಷ್ಮಜೀವಿಗಳ ಬಳಕೆಯನ್ನು ಸುಲಭಗೊಳಿಸುತ್ತದೆ.',
  'a046': 'ಸರ್ವವ್ಯಾಪಿ ಕಂಪ್ಯೂಟಿಂಗ್ ತಂತ್ರಜ್ಞಾನವು ನಮ್ಮ ಮನೆ ಮತ್ತು ನಗರ ಪರಿಸರದಲ್ಲಿ ಬುದ್ಧಿವಂತಿಕೆಯನ್ನು ಸರಾಗವಾಗಿ ಸಂಯೋಜಿಸುತ್ತದೆ.',
  'a047': 'ಯಂತ್ರ ಕಲಿಕೆಯ ಮಾದರಿಗಳು ತಪ್ಪು ತೀರ್ಮಾನಗಳನ್ನು ತಡೆಯಲು ಕಟ್ಟುನಿಟ್ಟಾದ ಡೇಟಾ ಶುದ್ಧೀಕರಣವನ್ನು ಬಯಸುತ್ತವೆ.',
  'a048': 'ಡೀಪ್‌ಫೇಕ್ ತಂತ್ರಜ್ಞಾನದ ಹರಡುವಿಕೆಯು ಡಿಜಿಟಲ್ ಸಾಕ್ಷ್ಯಗಳ ಸತ್ಯಾಸತ್ಯತೆಯ ಬಗ್ಗೆ ಗಂಭೀರ ಸವಾಲುಗಳನ್ನು ಒಡ್ಡುತ್ತದೆ.',
  'a049': 'ಸರ್ವರ್ ಸ್ಥಗಿತದಿಂದ ರಕ್ಷಣೆ ಪಡೆಯಲು ಕ್ಲೌಡ್ ವ್ಯವಸ್ಥೆಯಲ್ಲಿ ಭೌಗೋಳಿಕವಾಗಿ ಹರಡಿದ ಬ್ಯಾಕಪ್ ವ್ಯವಸ್ಥೆ ಅಗತ್ಯ.',
  'a050': 'ಬಯೋಮೆಟ್ರಿಕ್ ಭದ್ರತಾ ಮಾನದಂಡಗಳು ಬಳಕೆದಾರರ ಅನುಕೂಲ ಮತ್ತು ಸಾಂವಿಧಾನಿಕ ಗೌಪ್ಯತೆಯ ರಕ್ಷಣೆಯನ್ನು ಸಮತೋಲನಗೊಳಿಸಬೇಕು.',
  'a051': 'ನ್ಯೂರಲ್ ನೆಟ್‌ವರ್ಕ್‌ಗಳ ಮೂಲಕ ಕಂಪ್ಯೂಟರ್ ಭಾಷಾ ಪ್ರಕ್ರಿಯೆಯು ಮಾನವನ ಭಾಷಾ ಗ್ರಹಿಕೆಯನ್ನು ಅನುಕರಿಸುತ್ತದೆ.',
  'a052': 'ಸೈಬರ್ ಯುದ್ಧ ತಂತ್ರಗಳು ನಾಗರಿಕ ಮೂಲಸೌಕರ್ಯಗಳ ಕಾರ್ಯಾಚರಣೆಯ ಸಮಗ್ರತೆಗೆ ಅಪಾಯವನ್ನುಂಟುಮಾಡುತ್ತಿವೆ.',
  'a053': 'ನ್ಯಾನೊತಂತ್ರಜ್ಞಾನವು ಉತ್ತಮ ವಿದ್ಯುತ್ ವಾಹಕತೆ ಹೊಂದಿರುವ ಬಲವಾದ ವಸ್ತುಗಳ ಪರಮಾಣು ಮಟ್ಟದ ತಯಾರಿಕೆಯನ್ನು ಶಕ್ತಗೊಳಿಸುತ್ತದೆ.',
  'a054': 'ಸಾಫ್ಟ್‌ವೇರ್ ಉಪಕರಣಗಳ ಸುಲಭ ಲಭ್ಯತೆಯು ತಂತ್ರಜ್ಞಾನೇತರ ಸಂಸ್ಥಾಪಕರಿಗೂ ದೊಡ್ಡ ಅಪ್ಲಿಕೇಶನ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಲು ಶಕ್ತಿ ನೀಡುತ್ತದೆ.',
  'a055': 'ಹ್ಯೂರಿಸ್ಟಿಕ್ ತಂತ್ರಜ್ಞಾನವು ಸಂಕೀರ್ಣ ಗಣಿತದ ಸಮಸ್ಯೆಗಳಿಗೆ ಕಾರ್ಯಸಾಧ್ಯವಾದ ಅಂದಾಜು ಪರಿಹಾರಗಳನ್ನು ನೀಡುತ್ತದೆ.',
  'a056': 'ಎಡ್ಜ್ ಕಂಪ್ಯೂಟಿಂಗ್ ಡೇಟಾವನ್ನು ಅದರ ಉತ್ಪಾದನಾ ಸ್ಥಳದಲ್ಲೇ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುವ ಮೂಲಕ ವಿಳಂಬವನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.',
  'a057': 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಮತ್ತು ರೊಬೊಟಿಕ್ಸ್‌ನ ಸಂಗಮವು ಮಾನವ ಶ್ರಮದ ಯಾಂತ್ರೀಕರಣದ ಗಡಿಗಳನ್ನು ಮರುವ್ಯಾಖ್ಯಾನಿಸುತ್ತಿದೆ.',
  'a058': 'ಕಟ್ಟುನಿಟ್ಟಾದ ಗೂಢಲಿಪೀಕರಣವು ಬ್ಲಾಕ್‌ಚೈನ್‌ನಲ್ಲಿನ ಹಿಂದಿನ ವಹಿವಾಟು ದಾಖಲೆಗಳ ಬದಲಾಯಿಸಲಾಗದ ಸುರಕ್ಷತೆಯನ್ನು ಖಾತರಿಪಡಿಸುತ್ತದೆ.',
  'a059': 'ಸಾಮಾಜಿಕ ಪ್ರಗತಿಯು ಕೇವಲ ಯಾಂತ್ರಿಕ ಆವಿಷ್ಕಾರಗಳಿಂದಲೇ ಮುನ್ನಡೆಯುತ್ತದೆ ಎಂದು ಭಾವಿಸುವುದು ತಪ್ಪು.',
  'a060': 'ಏಕರೂಪದ ಮಾನದಂಡಗಳು ವಿವಿಧ ಆರೋಗ್ಯ ಡೇಟಾಬೇಸ್‌ಗಳಿಗೆ ವೈದ್ಯಕೀಯ ದಾಖಲೆಗಳನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಹಂಚಿಕೊಳ್ಳಲು ಅನುಮತಿಸುತ್ತವೆ.',
  'a061': 'ಕೈಗಾರಿಕಾ ಸಮಾಜದ ನೈತಿಕ ಅವನತಿಯನ್ನು ವಿವರಿಸಲು ಲೇಖಕರು ಮಾರ್ಮಿಕ ಸಾಂಕೇತಿಕ ರೂಪಕಗಳನ್ನು ಬಳಸುತ್ತಾರೆ.',
  'a062': 'ಆಕೆಯ ಕಾವ್ಯದ ಚಿತ್ರಣವು ಗತಕಾಲದ ನೆನಪುಗಳು ಮತ್ತು ಆತ್ಮಾವಲೋಕನದೊಂದಿಗೆ ಆಳವಾಗಿ ಧ್ವನಿಸುತ್ತದೆ.',
  'a063': 'ಸಂಗೀತ ನಿರ್ದೇಶಕರ ಸೂಕ್ಷ್ಮ ವ್ಯಾಖ್ಯಾನವು ಸಿಂಫನಿಯ ಸೂಕ್ಷ್ಮ ನಾದಗಳು ಮತ್ತು ಲಯಬದ್ಧತೆಯನ್ನು ಎತ್ತಿ ತೋರಿಸಿತು.',
  'a064': 'ವಿಕ್ಟೋರಿಯನ್ ಸಾಹಿತ್ಯದಲ್ಲಿ ಪಿತೃಪ್ರಭುತ್ವದ ಪ್ರಭಾವವನ್ನು ಹೇಗೆ ಪ್ರಶ್ನಿಸಲಾಗಿದೆ ಎಂಬುದನ್ನು ಸಾಹಿತ್ಯ ವಿಮರ್ಶೆಯು ಪರಿಶೀಲಿಸುತ್ತದೆ.',
  'a065': 'ಕಲಾವಿದೆಯು ತನ್ನ ಕಲಾಕೃತಿಯಲ್ಲಿ ಕಚ್ಚಾ ಕಾಂಕ್ರೀಟ್ ಜೊತೆಗೆ ಅರಳಿದ ಚೆರ್ರಿ ಕೊಂಬೆಗಳನ್ನು ಅದ್ಭುತವಾಗಿ ಸಂಯೋಜಿಸಿದಳು.',
  'a066': 'ಚಿತ್ರಮಂದಿರದ ಕತ್ತಲೆ ಮತ್ತು ಬೆಳಕಿನ ತಂತ್ರಜ್ಞಾನವು ಅಪರಾಧ ಕಥೆಗೆ ನಿಗೂಢ ಗಾಂಭೀರ್ಯವನ್ನು ತುಂಬಿತು.',
  'a067': 'ನಾಯಕನ ದುರಹಂಕಾರವು ಅಂತಿಮವಾಗಿ ನಾಟಕದ ಕೊನೆಯಲ್ಲಿ ಅವನ ದುರಂತ ಪತನಕ್ಕೆ ಕಾರಣವಾಯಿತು.',
  'a068': 'ಆಕೆಯ ಗದ್ಯ ಶೈಲಿಯು ಸುಮಧುರ ಲಯ, ವ್ಯಾಕರಣ ಕೌಶಲ್ಯ ಮತ್ತು ಭಾಷಾ ನಿಖರತೆಯಿಂದ ಕೂಡಿದೆ.',
  'a069': 'ವಸ್ತುಸಂಗ್ರಹಾಲಯದ ಪ್ರದರ್ಶನವು ಸಾಂಪ್ರದಾಯಿಕ ಸೌಂದರ್ಯವನ್ನು ಸವಾಲು ಮಾಡುವ ಆರು ದಶಕಗಳ ಆಧುನಿಕ ಶಿಲ್ಪಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿತು.',
  'a070': 'ಮ್ಯಾಜಿಕಲ್ ರಿಯಲಿಸಂ ಸಾಮಾನ್ಯ ದೈನಂದಿನ ವಾಸ್ತವ ಮತ್ತು ಮಾಂತ್ರಿಕ ವಿಸ್ಮಯಗಳ ನಡುವಿನ ಗಡಿಯನ್ನು ಸರಾಗವಾಗಿ ಬೆಸೆಯುತ್ತದೆ.',
  'a071': 'ನಾಟಕದ ಏಕಪಾತ್ರಾಭಿನಯವು ಮರ್ತ್ಯತೆಯನ್ನು ಆಲೋಚಿಸುವ ರಾಜನ ಅಸ್ತಿತ್ವವಾದಿ ಆತಂಕಕ್ಕೆ ದನಿ ನೀಡಿತು.',
  'a072': 'ಶಾಸ್ತ್ರೀಯ ಮಹಾಕಾವ್ಯಗಳು ಸಾಟಿಯಿಲ್ಲದ ಶೌರ್ಯ, ಯುದ್ಧ ಧೈರ್ಯ ಮತ್ತು ವಂಶದ ಗೌರವಕ್ಕೆ ನಿಷ್ಠೆಯನ್ನು ಕೊಂಡಾಡುತ್ತವೆ.',
  'a073': 'ಬುಡಕಟ್ಟು ಮೌಖಿಕ ಸಂಪ್ರದಾಯಗಳು ಶತಮಾನಗಳಿಂದ ಪರಿಸರ ಜ್ಞಾನವನ್ನು ಹೇಗೆ ಸಂರಕ್ಷಿಸಿವೆ ಎಂಬುದನ್ನು ಸಾಕ್ಷ್ಯಚಿತ್ರವು ತೋರಿಸಿತು.',
  'a074': 'ಅವರ ವಿಡಂಬನಾತ್ಮಕ ಬರಹವು ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮದ ಶ್ರೀಮಂತರ ದುರಹಂಕಾರ ಮತ್ತು ಆಡಂಬರವನ್ನು ಹಾಸ್ಯ ಮಾಡುತ್ತದೆ.',
  'a075': 'ಸರಳತಾವಾದಿ ಸಂಗೀತ ಸಂಯೋಜಕರು ಸೂಕ್ಷ್ಮ ಸ್ವರ ಬದಲಾವಣೆಗಳ ಮೂಲಕ ಮೋಡಿಮಾಡುವ ನಾದಲೋಕವನ್ನು ಸೃಷ್ಟಿಸುತ್ತಾರೆ.',
  'a076': 'ಜಾನಪದ ಕಥೆಗಳು ಸಾಮೂಹಿಕ ಸುಪ್ತ ಮನಸ್ಸಿನ ನಂಬಿಕೆಗಳು ಮತ್ತು ನೈತಿಕ ಎಚ್ಚರಿಕೆಗಳ ಮಾನವಶಾಸ್ತ್ರೀಯ ಭಂಡಾರವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ.',
  'a077': 'ಸಾಮಾಜಿಕ ಬದಲಾವಣೆಯ ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಕಾದಂಬರಿಕಾರರು ಯೌವನದ ಕ್ಷಣಿಕ ಸೌಂದರ್ಯವನ್ನು ಸುಂದರವಾಗಿ ಸೆರೆಹಿಡಿಯುತ್ತಾರೆ.',
  'a078': 'ವಾಸ್ತುಶಿಲ್ಪಿಗಳು ಐತಿಹಾಸಿಕ ಕಟ್ಟಡಗಳನ್ನು ನಗರದ ಕೆಡವftÂುವಿಕೆಯಿಂದ ರಕ್ಷಿಸಲು ಶ್ರಮಿಸಿದರು.',
  'a079': 'ಭವ್ಯ ನೈಸರ್ಗಿಕ ನೋಟಗಳು ಬ್ರಹ್ಮಾಂಡದಲ್ಲಿ ಮಾನವನ ಅಲ್ಪ ಅಸ್ತಿತ್ವವನ್ನು ನೆನಪಿಸಿ ವಿನಮ್ರ ಗೌರವವನ್ನು ಮೂಡಿಸುತ್ತವೆ.',
  'a080': 'ನಾಟಕಕಾರರು ಮೌನ ಮತ್ತು ಮಾರ್ಮಿಕ ಸಂಭಾಷಣೆಗಳ ಮೂಲಕ ಮಾನಸಿಕ ಆತಂಕವನ್ನು ಅದ್ಭುತವಾಗಿ ನಿರ್ಮಿಸುತ್ತಾರೆ.',
  'a081': 'ಏರುತ್ತಿರುವ ಹಣದುಬ್ಬರದ ಒತ್ತಡವನ್ನು ಎದುರಿಸಲು ಕೇಂದ್ರ ಬ್ಯಾಂಕ್ ಹಣಕಾಸಿನ ಬಿಗಿ ಕ್ರಮಗಳನ್ನು ಜಾರಿಗೆ ತಂದಿತು.',
  'a082': 'ಭೌಗೋಳಿಕ ರಾಜಕೀಯ ಉದ್ವಿಗ್ನತೆಯು ಜಾಗತಿಕ ಪೂರೈಕೆ ಸರಪಳಿಗಳನ್ನು ಅಸ್ತವ್ಯಸ್ತಗೊಳಿಸಿತು ಮತ್ತು ಸರಕುಗಳ ಬೆಲೆ ಏರಿಕೆಗೆ ಕಾರಣವಾಯಿತು.',
  'a083': 'ನೇರ ಮಿಲಿಟರಿ ಸಂಪರ್ಕ ಮಾರ್ಗಗಳನ್ನು ಸ್ಥಾಪಿಸುವ ಮೂಲಕ ರಾಜತಾಂತ್ರಿಕರು ಸಮುದ್ರ ಗಡಿ ಬಿಕ್ಕಟ್ಟನ್ನು ತಗ್ಗಿಸಲು ಯತ್ನಿಸಿದರು.',
  'a084': 'ಹಣಕಾಸಿನ ಮಿತವ್ಯಯ ಕಾರ್ಯಕ್ರಮಗಳು ಸಾರ್ವಜನಿಕ ಪ್ರತಿಭಟನೆಗಳು ಮತ್ತು ರಾಜಕೀಯ ಅಸಮಾಧಾನಕ್ಕೆ ಕಾರಣವಾಗುತ್ತವೆ.',
  'a085': 'ಸಾರ್ವಭೌಮ ಸಂಪತ್ತು ನಿಧಿಗಳು ವಿವಿಧ ಅಂತಾರಾಷ್ಟ್ರೀಯ ಪೋರ್ಟ್‌ಫೋಲಿಯೊಗಳಲ್ಲಿ ಕಾರ್ಯತಂತ್ರದ ಬಂಡವಾಳ ಹೂಡಿಕೆ ಮಾಡುತ್ತವೆ.',
  'a086': 'ಬಹುಪಕ್ಷೀಯ ವ್ಯಾಪಾರ ಒಪ್ಪಂದವು ಕಠಿಣ ಸುಂಕಗಳನ್ನು ರದ್ದುಗೊಳಿಸಿತು ಮತ್ತು ಗಡಿಯಾಚೆಗಿನ ಕಸ್ಟಮ್ಸ್ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಸುಲಭಗೊಳಿಸಿತು.',
  'a087': 'ನ್ಯಾಯಾಂಗ ಸ್ವಾತಂತ್ರ್ಯವು ಪ್ರಜಾಪ್ರಭುತ್ವದ ಹೊಣೆಗಾರಿಕೆ ಮತ್ತು ಸಾಂವಿಧಾನಿಕ ಆಡಳಿತದ ಮೂಲಾಧಾರವಾಗಿದೆ.',
  'a088': 'ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ಏಕಸ್ವಾಮ್ಯ ಸಾಧಿಸಲು ಯತ್ನಿಸಿದ್ದಕ್ಕಾಗಿ ಮತ್ತು ನಿಯಮ ಉಲ್ಲಂಘಿಸಿದ್ದಕ್ಕಾಗಿ ಕಂಪನಿಯು ತೀವ್ರ ದಂಡವನ್ನು ಎದುರಿಸಿತು.',
  'a089': 'ದ್ವಿಪಕ್ಷೀಯ ಒಪ್ಪಂದಗಳು ರಾಯಭಾರ ನೆರವು ಮತ್ತು ಕಾನೂನು ಹಸ್ತಾಂತರಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಸ್ಪಷ್ಟ ನಿಯಮಗಳನ್ನು ಸ್ಥಾಪಿಸುತ್ತವೆ.',
  'a090': 'ವ್ಯಾಪಕ ಭ್ರಷ್ಟಾಚಾರವು ಸಾಂಸ್ಥಿಕ ನಂಬಿಕೆಯನ್ನು ಕುಂದಿಸುತ್ತದೆ ಮತ್ತು ನಾಗರಿಕ ಮೂಲಸೌಕರ್ಯ ಅಭಿವೃದ್ಧಿಯನ್ನು ಹಾಳುಮಾಡುತ್ತದೆ.',
  'a091': 'ಹೂಡಿಕೆದಾರರು ಮುಂದಿನ ಹಣಕಾಸು ಒದಗಿಸುವ ಮೊದಲು ಘಟಕ ಆರ್ಥಿಕತೆಯ ಸ್ಪಷ್ಟ ಪುರಾವೆಗಳನ್ನು ಕೋರಿದರು.',
  'a092': 'ಭಾರೀ ಕೈಗಾರಿಕೆಗಳಲ್ಲಿ ಇಂಗಾಲದ ಹೊರಸೂಸುವಿಕೆಯನ್ನು ತಗ್ಗಿಸಲು ನಿಯಂತ್ರಕ ಸಂಸ್ಥೆಯು ಕಟ್ಟುನಿಟ್ಟಾದ ಮಿತಿಗಳನ್ನು ವಿಧಿಸಿತು.',
  'a093': 'ಕಾರ್ಪೊರೇಟ್ ವರದಿಗಳಲ್ಲಿನ ವ್ಯತ್ಯಾಸಗಳು ಸ್ವತಂತ್ರ ವಿಧಿವಿಜ್ಞಾನ ಲೆಕ್ಕಪರಿಶೋಧನೆಗೆ ಕಾರಣವಾಯಿತು.',
  'a094': 'ಸಮಾನ ಸಂಪತ್ತು ಹಂಚಿಕೆಯು ದೀರ್ಘಕಾಲೀನ ಸಾಮಾಜಿಕ ಸೌಹಾರ್ದತೆಯನ್ನು ಬೆಳೆಸುತ್ತದೆ ಮತ್ತು ನಾಗರಿಕ ಅಶಾಂತಿಯನ್ನು ತಗ್ಗಿಸುತ್ತದೆ.',
  'a095': 'ರಾಜತಾಂತ್ರಿಕ ತಟಸ್ಥತೆಯು ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಮಧ್ಯಸ್ಥಗಾರರಿಗೆ ಯುದ್ಧನಿರತ ರಾಷ್ಟ್ರಗಳ ನಡುವೆ ಕದನವಿರಾಮ ತರಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.',
  'a096': 'ಸ್ಥೂಲ ಆರ್ಥಿಕ ಮುನ್ಸೂಚನಾ ಮಾದರಿಗಳು ಅನಿರೀಕ್ಷಿತ ಜಾಗತಿಕ ಬಿಕ್ಕಟ್ಟುಗಳನ್ನು ಊಹಿಸಲು ಹೆಣಗಾಡುತ್ತವೆ.',
  'a097': 'ಕಾನೂನು ನ್ಯಾಯಮಂಡಳಿಯು ನೆರೆಯ ದ್ವೀಪ ರಾಷ್ಟ್ರಗಳ ನಡುವಿನ ಸಂಕೀರ್ಣ ಕಡಲ ಗಡಿ ವಿವಾದವನ್ನು ಇತ್ಯರ್ಥಪಡಿಸಿತು.',
  'a098': 'ಕಂಪನಿ ಮುಚ್ಚಿಹೋಗುವುದನ್ನು ತಪ್ಪಿಸಲು ತಜ್ಞರು ಸಮಗ್ರ ಸಾಲ ಮರುಹೊಂದಾಣಿಕೆಯನ್ನು ಯೋಜಿಸಿದರು.',
  'a099': 'ತೆರಿಗೆ ಸ್ವರ್ಗಗಳು ಅಂತರರಾಷ್ಟ್ರೀಯ ಲಾಭ ವರ್ಗಾವಣೆಯನ್ನು ಸುಗಮಗೊಳಿಸುವ ಮೂಲಕ ರಾಷ್ಟ್ರೀಯ ತೆರಿಗೆ ಸಾರ್ವಭೌಮತ್ವವನ್ನು ಕುಗ್ಗಿಸುತ್ತವೆ.',
  'a100': 'ನಾಗರಿಕ ಜಾಗೃತಿ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಚರ್ಚೆಗಳು ಸರ್ವಾಧಿಕಾರಿ ರಾಜಕೀಯ ಪ್ರವೃತ್ತಿಗಳಿಗೆ ಪ್ರಬಲ ರಕ್ಷಣಾ ಕವಚಗಳಾಗಿವೆ.',
  'a101': 'ಕಾರ್ಯಾಚರಣೆಯ ಚುರುಕುತನ ಮತ್ತು ಷೇರುದಾರರ ಲಾಭವನ್ನು ಹೆಚ್ಚಿಸಲು ಸಂಸ್ಥೆಯು ಅಪ್ರಮುಖ ಅಂಗಸಂಸ್ಥೆಗಳನ್ನು ಮಾರಾಟ ಮಾಡಿತು.',
  'a102': 'ಶಿಥಿಲಗೊಂಡಿರುವ ರಾಷ್ಟ್ರೀಯ ಸಾರಿಗೆ ಮೂಲಸೌಕರ್ಯವನ್ನು ನವೀಕರಿಸಲು ಉಭಯಪಕ್ಷೀಯ ಶಾಸನವನ್ನು ಅನುಮೋದಿಸಲಾಯಿತು.',
  'a103': 'ಕಾನೂನುಬಾಹಿರ ಶಸ್ತ್ರಾಸ್ತ್ರ ಜಾಲಗಳನ್ನು ಗುರಿಯಾಗಿಸಲು ಆರ್ಥಿಕ ನಿರ್ಬಂಧಗಳನ್ನು ನಿಖರವಾಗಿ ರೂಪಿಸಲಾಯಿತು.',
  'a104': 'ಸಾಲದ ರೇಟಿಂಗ್ ಕುಸಿತದ ನಂತರ ದೇಶದ ಕರೆನ್ಸಿ ಮೌಲ್ಯವು ತೀವ್ರವಾಗಿ ಕುಸಿಯಿತು.',
  'a105': 'ನ್ಯೂಯಾರ್ಕ್ ಕನ್ವೆನ್ಷನ್ ಅಡಿಯಲ್ಲಿ ಅಂತರರಾಷ್ಟ್ರೀಯ ಮಧ್ಯಸ್ಥಿಕೆ ತೀರ್ಪುಗಳನ್ನು ಗಡಿಯಾಚೆ ಜಾರಿಗೆ ತರಲಾಗುತ್ತದೆ.',
  'a106': 'ಅಂತರ್-ಬ್ಯಾಂಕ್ ಸಾಲ ಮಾರುಕಟ್ಟೆಯಲ್ಲಿನ ನಗದು ಕೊರತೆಯು ಕೇಂದ್ರೀಯ ಬ್ಯಾಂಕಿನ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನು ಬಯಸಿತು.',
  'a107': 'ಪರಿಸರ ಒಪ್ಪಂದವು ಜೌಗು ಪ್ರದೇಶಗಳ ಸಂರಕ್ಷಣೆಗಾಗಿ ಬಹುಪಕ್ಷೀಯ ಬದ್ಧತೆಗಳನ್ನು ಕಡ್ಡಾಯಗೊಳಿಸುತ್ತದೆ.',
  'a108': 'ಸ್ಪರ್ಧಾತ್ಮಕ ಮಾರುಕಟ್ಟೆ ಅಪಾಯಗಳನ್ನು ಉಲ್ಲೇಖಿಸಿ ನಿಯಂತ್ರಕರು ಟೆಲಿಕಾಂ ವಿಲೀನವನ್ನು ತಡೆದರು.',
  'a109': 'ಹೆಚ್ಚುತ್ತಿರುವ ವೃದ್ಧಾಪ್ಯದ ಜನಸಂಖ್ಯೆಯು ಪಿಂಚಣಿ ವ್ಯವಸ್ಥೆಗೆ ಅಗಾಧ ಆರ್ಥಿಕ ಸವಾಲುಗಳನ್ನು ಒಡ್ಡುತ್ತದೆ.',
  'a110': 'ಪಾರದರ್ಶಕ ನಿಯಮಗಳು ವಿದೇಶಿ ನೇರ ಹೂಡಿಕೆಯನ್ನು ಆಕರ್ಷಿಸುತ್ತವೆ ಮತ್ತು ಆರ್ಥಿಕ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸುತ್ತವೆ.',
  'a111': 'ಅರಿವಿನ ಚಿಕಿತ್ಸೆಯ ನಂತರ ಮೆದುಳಿನ ನರಮಂಡಲದಲ್ಲಿ ಗಮನಾರ್ಹ ಸಕಾರಾತ್ಮಕ ಹೊಂದಾಣಿಕೆಗಳು ಕಂಡುಬಂದವು.',
  'a112': 'ಸೋಂಕುಶಾಸ್ತ್ರ ವಿಭಾಗವು ಪ್ರಾಣಿಗಳಿಂದ ಹರಡಿದ ಹೊಸ ರೋಗಾಣುವಿನ ಮಾರ್ಗವನ್ನು ದಾಖಲಿಸಿತು.',
  'a113': 'ವೈಯಕ್ತಿಕ ಆನುವಂಶಿಕ ವಿವರಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಕೀಮೋಥೆರಪಿ ಪ್ರಮಾಣವನ್ನು ನಿಗದಿಪಡಿಸಲು ತಳಿಶಾಸ್ತ್ರವು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
  'a114': 'ಎಪಿಜೆನೆಟಿಕ್ ಬದಲಾವಣೆಗಳು ಡಿಎನ್‌ಎ ಮೂಲ ರಚನೆಯನ್ನು ಬದಲಾಯಿಸದೆ ಜೀನ್ ಕಾರ್ಯನಿರ್ವಹಣೆಯನ್ನು ನಿಯಂತ್ರಿಸುತ್ತವೆ.',
  'a115': 'ದೀರ್ಘಕಾಲದ ಮಾನಸಿಕ ಒತ್ತಡದಿಂದ ಹೆಚ್ಚಾಗುವ ಕಾರ್ಟಿಸೋಲ್ ರೋಗನಿರೋಧಕ ಶಕ್ತಿಯನ್ನು ಕುಂಠಿತಗೊಳಿಸುತ್ತದೆ.',
  'a116': 'ಮಾನಸಿಕ ಸ್ಥೈರ್ಯವು ಕಠಿಣ ಸವಾಲುಗಳನ್ನು ಸಕಾರಾತ್ಮಕವಾಗಿ ಸ್ವೀಕರಿಸುವ ಅರಿವಿನ ಹೊಂದಾಣಿಕೆಯನ್ನು ಒಳಗೊಂಡಿದೆ.',
  'a117': 'ಕ್ಲಿನಿಕಲ್ ಪ್ರಯೋಗವು ಹೊಸ ಔಷಧಿಯ ಚಿಕಿತ್ಸಕ ಪರಿಣಾಮಕಾರಿತ್ವವನ್ನು ದೃಢಪಡಿಸಿತು.',
  'a118': 'ಕರುಳಿನಲ್ಲಿನ ಬ್ಯಾಕ್ಟೀರಿಯಾದ ಅಸಮತೋಲನವು ದೀರ್ಘಕಾಲಿಕ ಉರಿಯೂತದ ಕಾಯಿಲೆಗಳಿಗೆ ಕಾರಣವಾಗುತ್ತದೆ.',
  'a119': 'ನಿದ್ರೆಯ ಭಂಗವು ಮೆದುಳಿನಲ್ಲಿನ ಹಾನಿಕಾರಕ ವಿಷಕಾರಿ ಪ್ರೋಟೀನ್‌ಗಳ ಶುದ್ಧೀಕರಣವನ್ನು ದುರ್ಬಲಗೊಳಿಸುತ್ತದೆ.',
  'a120': 'ಅರಿವಿನ ವರ್ತನೆಯ ಚಿಕಿತ್ಸೆಯು ನಕಾರಾತ್ಮಕ ಆಲೋಚನೆಗಳನ್ನು ನಿವಾರಿಸಲು ಮಾನಸಿಕ ಸಾಧನಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ.',
  'a121': 'ಜೈವಿಕ ವಿಘಟನೀಯ ನ್ಯಾನೊವಾಹಕಗಳ ಸಂಶ್ಲೇಷಣೆಯು ಕ್ಯಾನ್ಸರ್ ಔಷಧವನ್ನು ನಿಖರವಾಗಿ ತಲುಪಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
  'a122': 'ರಕ್ತಸ್ರಾವದ ಆಘಾತವನ್ನು ತಡೆಗಟ್ಟಲು ರಕ್ತದೊತ್ತಡ ಸ್ಥಿರೀಕರಣ ಚಿಕಿತ್ಸೆಯನ್ನು ತಕ್ಷಣ ನೀಡಲಾಯಿತು.',
  'a123': 'ಮಾನಸಿಕ-ದೈಹಿಕ ಲಕ್ಷಣಗಳು ಮೆದುಳು ಮತ್ತು ದೇಹದ ನಡುವಿನ ನಿಕಟ ದ್ವಿಮುಖ ಸಂವಹನವನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತವೆ.',
  'a124': 'ತಜ್ಞರು ಚಯಾಪಚಯ ನಿಯಂತ್ರಣಕ್ಕೆ ಕಾರಣವಾಗುವ ಹಾರ್ಮೋನುಗಳ ಏರಿಳಿತಗಳನ್ನು ತನಿಖೆ ಮಾಡಿದರು.',
  'a125': 'ಮೆದುಳಿನ ಹಿಪೊಕ್ಯಾಂಪಸ್ ಸರ್ಕ್ಯೂಟ್‌ಗಳಲ್ಲಿ ನರಗಳ ಸಂಪರ್ಕ ಬಲವರ್ಧನೆಯನ್ನು ತಪಾಸಣೆಗಳು ಖಚಿತಪಡಿಸಿದವು.',
  'a126': 'ರೋಗನಿರೋಧಕ ವ್ಯವಸ್ಥೆಯು ತನ್ನದೇ ಜೀವಕೋಶಗಳನ್ನು ಗುರುತಿಸುವಲ್ಲಿ ವಿಫಲವಾದಾಗ ಆಟೋಇಮ್ಯೂನ್ ಕಾಯಿಲೆಗಳು ಉಂಟಾಗುತ್ತವೆ.',
  'a127': 'ಹೃದಯ ಮತ್ತು ಶ್ವಾಸಕೋಶದ ಸದೃಢತೆಯು ಅಕಾಲಿಕ ಮರಣದ ಅಪಾಯವನ್ನು ತಗ್ಗಿಸುವ ಪ್ರಮುಖ ಜೈವಿಕ ಸೂಚಕವಾಗಿದೆ.',
  'a128': 'ಮೆದುಳಿನ ನರಪ್ರೇಕ್ಷಕಗಳ ಅಸಮತೋಲನವು ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುವ ಸಾಮರ್ಥ್ಯವನ್ನು ಕುಂಠಿತಗೊಳಿಸುತ್ತದೆ.',
  'a129': 'ಟೆಲೋಮಿಯರ್ ಸವೆತವು ಜೈವಿಕ ವಯಸ್ಸಾಗುವಿಕೆಯ ಮೂಲಭೂತ ಜೀವಕೋಶದ ಲಕ್ಷಣವೆಂದು ಗುರುತಿಸಲ್ಪಟ್ಟಿದೆ.',
  'a130': 'ಸಸ್ಯ ಆಧಾರಿತ ಆಹಾರ ಪದ್ಧತಿಯು ಚಯಾಪಚಯ ಆರೋಗ್ಯವನ್ನು ಉತ್ತಮಗೊಳಿಸುತ್ತದೆ ಎಂದು ಪೌಷ್ಟಿಕತಜ್ಞರು ದೃಢಪಡಿಸಿದ್ದಾರೆ.',
  'a131': 'ಗಮನವಿಟ್ಟು ಉಸಿರಾಟ ನಿಯಂತ್ರಣ ಮಾಡುವುದು ಆರೋಗ್ಯಕ್ಕೆ ಅತ್ಯಂತ ಉಪಯುಕ್ತವೆಂದು ಸಂಶೋಧನೆಗಳು ಸಾಬೀತುಪಡಿಸಿವೆ.',
  'a132': 'ರಕ್ತನಾಳಗಳ ಒಳಪದರದ ಅಪಸಾಮಾನ್ಯ ಕ್ರಿಯೆಯು ಅಪಧಮನಿ ಕಾಯಿಲೆಗಳಿಗೆ ಮೂಲ ಕಾರಣವಾಗಿದೆ.',
  'a133': 'ಮನೋವೈದ್ಯರು ತಾತ್ಕಾಲಿಕ ಪರಿಸ್ಥಿತಿಯ ದುಃಖ ಮತ್ತು ದೀರ್ಘಕಾಲದ ಖಿನ್ನತೆಯ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಿದರು.',
  'a134': 'ಸ್ನಾಯು ಪುನಶ್ಚೇತನಕ್ಕೆ ಸ್ನಾಯುರಜ್ಜು ಬಲವನ್ನು ಮರಳಿ ಪಡೆಯಲು ಕ್ರಮೇಣ ವ್ಯಾಯಾಮದ ಅಗತ್ಯವಿದೆ.',
  'a135': 'ತಳಿ ಅನುಕ್ರಮಣಿಕೆಯು ಅಪರೂಪದ ಚಯಾಪಚಯ ಕಾಯಿಲೆಗೆ ಕಾರಣವಾಗುವ ವಂಶವಾಹಿ ರೂಪಾಂತರವನ್ನು ಪ್ರತ್ಯೇಕಿಸಿತು.',
  'a136': 'ಸೃಜನಶೀಲ ಕಲೆಗಳ ಮೂಲಕ ಭಾವನೆಗಳನ್ನು ವ್ಯಕ್ತಪಡಿಸುವುದು ಆಳವಾದ ಮಾನಸಿಕ ನವಚೈತನ್ಯವನ್ನು ನೀಡುತ್ತದೆ.',
  'a137': 'ನೈಸರ್ಗಿಕ ನಿದ್ರೆಯ ಚಕ್ರದ ಏರುಪೇರು ಗ್ಲೂಕೋಸ್ ಸಹಿಷ್ಣುತೆಯನ್ನು ಕುಂದಿಸುತ್ತದೆ ಮತ್ತು ರಕ್ತದೊತ್ತಡವನ್ನು ಹೆಚ್ಚಿಸುತ್ತದೆ.',
  'a138': 'ಮೂಳೆ ಶಸ್ತ್ರಚಿಕಿತ್ಸಕರು ಹರಿದ ಮಂಡಿಯ ಕಾರ್ಟಿಲೆಜ್ ಮೇಲೆ ಕನಿಷ್ಠ ಶಸ್ತ್ರಚಿಕಿತ್ಸೆಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಮಾಡಿದರು.',
  'a139': 'ವ್ಯವಸ್ಥಿತ ಉರಿಯೂತವು ಮೆದುಳಿನ ರಕ್ಷಣಾ ಗೋಡೆಯನ್ನು ದುರ್ಬಲಗೊಳಿಸಿ ವಯಸ್ಸಾದಂತೆ ಸ್ಮರಣಶಕ್ತಿ ಕುಗ್ಗುವಿಕೆಯನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ.',
  'a140': 'ಮೈಂಡ್‌ಫುಲ್‌ನೆಸ್ ತಂತ್ರಗಳು ಆಲೋಚನೆಗಳನ್ನು ನಿಗ್ರಹಿಸುವುದಕ್ಕಿಂತ ವಾಸ್ತವವನ್ನು ಸ್ವೀಕರಿಸುವುದನ್ನು ಕಲಿಸುತ್ತವೆ.',
  'a141': 'ದೀರ್ಘ ಉಪವಾಸದ ಸಮಯದಲ್ಲಿ ಜೀವಕೋಶದ ಸ್ವಯಂ-ಶುದ್ಧೀಕರಣ ಪ್ರಕ್ರಿಯೆಯು ಹಾನಿಗೊಳಗಾದ ಭಾಗಗಳನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ.',
  'a142': 'ಕಿವಿ ಒಳಗಿನ ಸಮತೋಲನ ವ್ಯವಸ್ಥೆಯ ದೋಷವು ದೈಹಿಕ ಸಮತೋಲನವನ್ನು ಕಷ್ಟಕರವಾಗಿಸುತ್ತದೆ.',
  'a143': 'ಅಡ್ಡಪರಿಣಾಮಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಮನೋವೈದ್ಯಕೀಯ ಔಷಧಿಗಳನ್ನು ಅತ್ಯಂತ ಸೂಕ್ಷ್ಮವಾಗಿ ಸರಿಹೊಂದಿಸಬೇಕು.',
  'a144': 'ಪ್ರಾಯೋಗಿಕ ಜೀವ ರಕ್ಷಕ ವಿಧಾನಗಳ ಚರ್ಚೆಯ ಸಮಯದಲ್ಲಿ ರೋಗಿಯ ಸ್ವಾಯತ್ತತೆಗೆ ಪ್ರಾಮುಖ್ಯತೆ ನೀಡಲಾಯಿತು.',
  'a145': 'ಆಳವಾದ ಭಾವನಾತ್ಮಕ ಸಹಾನುಭೂತಿಯು ವೈದ್ಯ ಮತ್ತು ರೋಗಿಯ ನಡುವಿನ ಚಿಕಿತ್ಸಕ ನಂಬಿಕೆಯನ್ನು ಬಲಪಡಿಸುತ್ತದೆ.',
  'a146': 'ಆಂತರಿಕ ಮಾನಸಿಕ ಆತಂಕಗಳನ್ನು ಮುಕ್ತವಾಗಿ ಹೇಳಿಕೊಂಡಾಗ ದೈಹಿಕ ನೋವಿನ ಲಕ್ಷಣಗಳು ಕಡಿಮೆಯಾಗುತ್ತವೆ.',
  'a147': 'ಆಕ್ಸಿಡೇಟಿವ್ ಒತ್ತಡವು ಜೀವಕೋಶದ ಶಕ್ತಿ ಕೇಂದ್ರಗಳನ್ನು ಹಾನಿಗೊಳಿಸುತ್ತದೆ ಮತ್ತು ಕ್ಷೀಣತೆಯನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ.',
  'a148': 'ಸಮಗ್ರ ಜೀವನಶೈಲಿ ಬದಲಾವಣೆಗಳು ಆರಂಭಿಕ ಹಂತದ ಹೃದ್ರೋಗವನ್ನು ಹಿಮ್ಮೆಟ್ಟಿಸುವಲ್ಲಿ ಅತ್ಯುತ್ತಮ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ.',
  'a149': 'ಮಾನಸಿಕ ಸಮೃದ್ಧಿಯು ಭಾವನಾತ್ಮಕ ಹುರುಪು, ಜೀವನದ ಉದ್ದೇಶ ಮತ್ತು ಬಲವಾದ ಸಾಮಾಜಿಕ ಸಂಬಂಧಗಳನ್ನು ಒಳಗೊಂಡಿರುತ್ತದೆ.',
  'a150': 'ಸಮಗ್ರ ಆರೋಗ್ಯ ಮಾದರಿಗಳು ಮಾನಸಿಕ-ದೈಹಿಕ ಚಿಕಿತ್ಸೆಗಳನ್ನು ಸಾಂಪ್ರದಾಯಿಕ ವೈದ್ಯಕೀಯದೊಂದಿಗೆ ಸಂಯೋಜಿಸುತ್ತವೆ.',
  'a151': 'ಸಾಂಸ್ಕೃತಿಕ ಪ್ರಾಬಲ್ಯವು ಹಿಂದುಳಿದ ಜನರ ಒಪ್ಪಿಗೆಯನ್ನು ಹೇಗೆ ಕುತಂತ್ರದಿಂದ ಪಡೆಯುತ್ತದೆ ಎಂಬುದನ್ನು ಸಮಾಜಶಾಸ್ತ್ರೀಯ ವಿಮರ್ಶೆಯು ಪ್ರಶ್ನಿಸಿತು.',
  'a152': 'ವೈಜ್ಞಾನಿಕ ಸಿದ್ಧಾಂತಗಳು ಸದಾ ತಾತ್ಕಾಲಿಕ ಮತ್ತು ಪರಿಷ್ಕರಣೆಗೆ ಮುಕ್ತವಾಗಿವೆ ಎಂದು ಜ್ಞಾನಮೀಮಾಂಸೆಯ ನಮ್ರತೆಯು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತದೆ.',
  'a153': 'ಪ್ರಜಾಪ್ರಭುತ್ವವು ಕಾರ್ಪೊರೇಟ್ ಪ್ರಭಾವವನ್ನು ತಡೆದುಕೊಳ್ಳಬಲ್ಲದೇ ಎಂದು ರಾಜಕೀಯ ತತ್ವಜ್ಞಾನಿ ಪರಿಶೀಲಿಸಿದರು.',
  'a154': 'ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮಗಳಲ್ಲಿನ ನಿರಂತರ ಹೋಲಿಕೆಗಳಿಂದಾಗಿ ಅಸ್ತಿತ್ವವಾದಿ ಹತಾಶೆಯು ಹೆಚ್ಚಾಗಿ ಉಲ್ಬಣಗೊಳ್ಳುತ್ತದೆ.',
  'a155': 'ನಿಜವಾದ ಬೌದ್ಧಿಕ ಸ್ವಾತಂತ್ರ್ಯಕ್ಕೆ ವಿರೋಧಿ ದೃಷ್ಟಿಕೋನಗಳ ಮುಕ್ತ ಸಂಪರ್ಕ ಅತ್ಯಗತ್ಯ ಎಂದು ಪ್ರಬಂಧವು ವಾದಿಸಿತು.',
  'a156': 'ಡಿಜಿಟಲ್ ಆವಿಷ್ಕಾರಗಳು ಆರ್ಥಿಕ ಅಸಮಾನತೆಗಳನ್ನು ತಾವಾಗಿಯೇ ಪರಿಹರಿಸುತ್ತವೆ ಎಂದು ಭಾವಿಸುವುದು ಅತಿಯಾದ ಮುಗ್ಧತೆ.',
  'a157': 'ಸುಸ್ಥಿರ ನಾಗರಿಕ ಸಮಾಜಕ್ಕೆ ಸರ್ಕಾರದ ಕಣ್ಗಾವಲಿನಿಂದ ಮುಕ್ತವಾದ ಸಾರ್ವಜನಿಕ ವೇದಿಕೆಗಳು ಅಗತ್ಯ.',
  'a158': 'ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆಯ ಬಗೆಗಿನ ನೈತಿಕ ಚರ್ಚೆಗಳು ಪಾರದರ್ಶಕತೆ ಮತ್ತು ಹೊಣೆಗಾರಿಕೆಗೆ ಆದ್ಯತೆ ನೀಡಬೇಕು.',
  'a159': 'ಪವಿತ್ರ ಸಾಂಸ್ಕೃತಿಕ ಸಂಪ್ರದಾಯಗಳನ್ನು ವಾಣಿಜ್ಯ ಲಾಭಕ್ಕಾಗಿ ದುರುಪಯೋಗಪಡಿಸಿಕೊಳ್ಳುವುದು ಸರಿಯಲ್ಲ.',
  'a160': 'ಪ್ರಚಾರ ವ್ಯವಸ್ಥೆಗಳು ಹೇಗೆ ವಿದೇಶಿ ದ್ವೇಷದ ಉನ್ಮಾದವನ್ನು ಸೃಷ್ಟಿಸಿದವು ಎಂಬುದನ್ನು ಸಾಕ್ಷ್ಯಚಿತ್ರವು ವಿವರಿಸಿತು.',
  'a161': 'ವಿಮರ್ಶಾತ್ಮಕ ಬೋಧನಾ ಪದ್ಧತಿಯು ಹಿಂದುಳಿದ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ವ್ಯವಸ್ಥಿತ ಶಕ್ತಿಯನ್ನು ಪ್ರಶ್ನಿಸಲು ಮತ್ತು ಸ್ವಾವಲಂಬಿಗಳಾಗಲು ಶಕ್ತಿ ನೀಡುತ್ತದೆ.',
  'a162': 'ಪರಿಸರ ಬಿಕ್ಕಟ್ಟು ಪ್ರಕೃತಿ ಕೇಂದ್ರಿತ ಸಮಾನತೆಯ ಕಡೆಗೆ ಸಂಪೂರ್ಣ ಚಿಂತನೆಯ ಬದಲಾವಣೆಯನ್ನು ಬಯಸುತ್ತದೆ.',
  'a163': 'ಆಕೆಯ ತೀಕ್ಷ್ಣ ವಿಮರ್ಶೆಯು ಪ್ರತಿಭೆಯ ಹೆಸರಿನಲ್ಲಿ ನಡೆಯುವ ವಂಶಪಾರಂಪರ್ಯ ಸವಲತ್ತುಗಳ ಭ್ರಮೆಯನ್ನು ಬಯಲುಮಾಡಿತು.',
  'a164': 'ಆಳವಾದ ತಾತ್ವಿಕ ಚಿಂತನೆಯು ಸಾವಿನ ಅನಿವಾರ್ಯ ವಾಸ್ತವವನ್ನು ಶಾಂತವಾಗಿ ಎದುರಿಸಲು ಮನುಷ್ಯನಿಗೆ ಶಕ್ತಿ ನೀಡುತ್ತದೆ.',
  'a165': 'ರಾಷ್ಟ್ರೀಯ ಭದ್ರತೆ ಮತ್ತು ವೈಯಕ್ತಿಕ ಗೌಪ್ಯತೆಯ ನಡುವಿನ ಸಾಂವಿಧಾನಿಕ ಸಂಘರ್ಷಗಳನ್ನು ಕಾನೂನು ತಜ್ಞರು ವಿಶ್ಲೇಷಿಸಿದರು.',
  'a166': 'ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮದ ಅಲ್ಗಾರಿದಮ್‌ಗಳು ಒಂದೇ ರೀತಿಯ ಅಭಿಪ್ರಾಯಗಳನ್ನು ಬಲಪಡಿಸುವ ಮೂಲಕ ರಾಜಕೀಯ ಧ್ರುವೀಕರಣವನ್ನು ಹೆಚ್ಚಿಸುತ್ತವೆ.',
  'a167': 'ಇತಿಹಾಸವನ್ನು ಮರೆಯುವುದು ಸಮಾಜಗಳನ್ನು ಹಳೆಯ ರಾಜಕೀಯ ದುರಂತಗಳನ್ನು ಪುನರಾವರ್ತಿಸಲು ಪ್ರೇರೇಪಿಸುತ್ತದೆ ಎಂದು ಲೇಖಕರು ಎಚ್ಚರಿಸಿದರು.',
  'a168': 'ಸಾಂಸ್ಥಿಕ ಅನ್ಯಾಯವನ್ನು ಎದುರಿಸುವಾಗ ನೈತಿಕ ನಾಯಕತ್ವವು ಅಚಲವಾದ ನೈತಿಕ ಧೈರ್ಯವನ್ನು ಬಯಸುತ್ತದೆ.',
  'a169': 'ವೈಯಕ್ತಿಕ ಸ್ವಾತಂತ್ರ್ಯ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಕಲ್ಯಾಣದ ನಡುವಿನ ಸಮತೋಲನವು ಆಧುನಿಕ ಸಂವಿಧಾನದ ತಿರುಳಾಗಿದೆ.',
  'a170': 'ನಿಜವಾದ ಬುದ್ಧಿವಂತಿಕೆಯು ಪಾಂಡಿತ್ಯದ ಪ್ರದರ್ಶನದಲ್ಲಿಲ್ಲ, ಬದಲಿಗೆ ದಯೆ ಮತ್ತು ಕರುಣೆಯ ಕ್ರಿಯೆಯಲ್ಲಿದೆ.',
  'a171': 'ವಿಭಿನ್ನ ಆಡಳಿತ ತತ್ವಗಳನ್ನು ಸರಿದೂಗಿಸಲು ಸಂವಿಧಾನ ಸಭೆಯು ದಣಿವರಿಯದೆ ಚರ್ಚಿಸಿತು.',
  'a172': 'ದೈನಂದಿನ ಸಂಭಾಷಣೆಯ ಮೂಲಕ ಸಾಮಾಜಿಕ ಪ್ರಪಂಚವು ಹೇಗೆ ನಿರ್ಮಾಣವಾಗುತ್ತದೆ ಎಂಬುದನ್ನು ಸಮಾಜಶಾಸ್ತ್ರವು ತನಿಖೆ ಮಾಡುತ್ತದೆ.',
  'a173': 'ಔಷಧ ಕಂಪನಿಗಳ ಒಕ್ಕೂಟವು ಕ್ಯಾನ್ಸರ್ ಕೋಶಗಳನ್ನು ನಿಖರವಾಗಿ ಗುರಿಯಾಗಿಸುವ ಪೆಪ್ಟೈಡ್ ಸಂಯುಕ್ತವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸಿತು.',
  'a174': 'ಸ್ಥೂಲ ಆರ್ಥಿಕ ನೀತಿಯು ತೆರಿಗೆ ರಿಯಾಯಿತಿಗಳ ಮೂಲಕ ಆರ್ಥಿಕ ಜಡತೆಯನ್ನು ನಿಯಂತ್ರಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ.',
  'a175': 'ಕಾನೂನು ವ್ಯಾಖ್ಯಾನವು ಸಂವಿಧಾನದ ಮೂಲ ಉದ್ದೇಶ ಮತ್ತು ಕಾಲಕ್ಕೆ ತಕ್ಕಂತೆ ಬದಲಾಗುವ ವ್ಯಾಖ್ಯಾನವನ್ನು ಪ್ರತ್ಯೇಕಿಸುತ್ತದೆ.',
  'a176': 'ನಮ್ಮ ಅತ್ಯಂತ ನಿಖರವಾದ ವೈಜ್ಞಾನಿಕ ಸಿದ್ಧಾಂತಗಳೂ ಸಹ ಪರಿಷ್ಕರಣೆಗೆ ಒಳಪಟ್ಟಿವೆ ಎಂದು ತತ್ತ್ವಶಾಸ್ತ್ರ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತದೆ.',
  'a177': 'ವಾಸ್ತುಶಿಲ್ಪಿ ಬಲಿಷ್ಠ ಕಲ್ಲಿನ ಕೆಲಸ ಮತ್ತು ಮರದ ಸುಂದರ ಕಮಾನುಗಳನ್ನು ನಗರ ಭವನದಲ್ಲಿ ಸಾಮರಸ್ಯದಿಂದ ಸಂಯೋಜಿಸಿದರು.',
  'a178': 'ಆಳವಾದ ನಂಬಿಕೆಗಳು ಹಠಾತ್ ಮುರಿದುಬಿದ್ದಾಗ ತೀವ್ರ ಅಸ್ತಿತ್ವವಾದಿ ಭಯ ಉಂಟಾಗುತ್ತದೆ.',
  'a179': 'ಕ್ರೆಡಿಟ್ ಸ್ಕೋರಿಂಗ್ ಅಲ್ಗಾರಿದಮ್‌ಗಳ ಅಸ್ಪಷ್ಟತೆಯು ಆರ್ಥಿಕ ತಾರತಮ್ಯವನ್ನು ರಹಸ್ಯವಾಗಿ ಮುಂದುವರಿಸುತ್ತದೆ.',
  'a180': 'ಗಡಿಯಾಚೆಗಿನ ಪರಿಸರ ಅವನತಿಯನ್ನು ನಿಭಾಯಿಸಲು ಬಹುಪಕ್ಷೀಯ ಒಪ್ಪಂದಗಳು ಅತ್ಯಗತ್ಯ ಎಂದು ರಾಜತಾಂತ್ರಿಕರು ಒತ್ತಿ ಹೇಳಿದರು.',
  'a181': 'ಸರ್ಕಾರಿ ಪ್ರಚಾರವು ಜನರ ಒಪ್ಪಿಗೆಯನ್ನು ಪಡೆಯಲು ಭಾಷಾ ಪದಗಳನ್ನು ಹೇಗೆ ತಿರುಚುತ್ತದೆ ಎಂಬುದನ್ನು ವಿಶ್ಲೇಷಣೆಯು ತೋರಿಸುತ್ತದೆ.',
  'a182': 'ಸಾಹಿತ್ಯ ವಿದ್ವಾಂಸರು ನಾಟಕದಲ್ಲಿ ವಿಧಿ ಮತ್ತು ಮಾನವ ಪ್ರಯತ್ನಗಳ ನಡುವಿನ ಪರಸ್ಪರ ಕ್ರಿಯೆಯನ್ನು ಪರಿಶೀಲಿಸಿದರು.',
  'a183': 'ಸೈಕೆಡೆಲಿಕ್ ಸಂಯುಕ್ತಗಳು ಮೆದುಳಿನಲ್ಲಿ ನರಗಳ ಬೆಳವಣಿಗೆ ಮತ್ತು ಹೊಂದಾಣಿಕೆಯನ್ನು ಉತ್ತೇಜಿಸುತ್ತವೆ ಎಂದು ಸಂಶೋಧನೆ ತೋರಿಸುತ್ತದೆ.',
  'a184': 'ಅಂತಾರಾಷ್ಟ್ರೀಯ ಜಲಪ್ರದೇಶದಲ್ಲಿ ಅಕ್ರಮ ಕಳ್ಳಸಾಗಣೆಯನ್ನು ತಡೆಯಲು ರಾಷ್ಟ್ರವು ತನ್ನ ಕಡಲ ಹಕ್ಕುಗಳನ್ನು ಚಲಾಯಿಸಿತು.',
  'a185': 'ವ್ಯಾವಹಾರಿಕ ತತ್ವಜ್ಞಾನವು ಸಿದ್ಧಾಂತಗಳನ್ನು ಕೇವಲ ಕಲ್ಪನೆಯಿಂದಲ್ಲ, ಪ್ರಾಯೋಗಿಕ ಫಲಿತಾಂಶಗಳಿಂದ ಮೌಲ್ಯಮಾಪನ ಮಾಡುತ್ತದೆ.',
  'a186': 'ವಸ್ತುಸಂಗ್ರಹಾಲಯವು ಆಧುನಿಕ ಶಿಲ್ಪಕಲೆಯ ರಾಜಕೀಯ ಆಧಾರಗಳನ್ನು ವಿಶ್ಲೇಷಿಸುವ ಪ್ರದರ್ಶನವನ್ನು ಆಯೋಜಿಸಿತು.',
  'a187': 'ಕಟ್ಟುನಿಟ್ಟಾದ ನಿಯಮಗಳು ವಂಚನೆಯ ಷೇರು ವ್ಯವಹಾರಗಳಲ್ಲಿ ತೊಡಗುವ ಕಂಪನಿ ಅಧಿಕಾರಿಗಳಿಗೆ ಶಿಕ್ಷೆ ವಿಧಿಸುತ್ತವೆ.',
  'a188': 'ಜೀವವೈವಿಧ್ಯತೆಯು ಪರಿಸರ ವ್ಯವಸ್ಥೆಗಳನ್ನು ಹಠಾತ್ ವಿನಾಶಕಾರಿ ಬದಲಾವಣೆಗಳಿಂದ ರಕ್ಷಿಸುತ್ತದೆ ಎಂದು ಪರಿಸರ ಸಿದ್ಧಾಂತವು ತೋರಿಸುತ್ತದೆ.',
  'a189': 'ಸಂಸದರು ಸಂಸತ್ತಿನ ಬಜೆಟ್ ಅಧಿಕಾರವನ್ನು ಕಾರ್ಯಾಂಗವು ಅತಿಕ್ರಮಿಸುವುದನ್ನು ತೀವ್ರವಾಗಿ ಖಂಡಿಸಿದರು.',
  'a190': 'ಮನೋವೈಜ್ಞಾನಿಕ ಮೌಲ್ಯಮಾಪನ ಸಾಧನಗಳು ವಿವಿಧ ಸಂಸ್ಕೃತಿಗಳಲ್ಲಿ ನಿಖರತೆ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಸೂಕ್ತ ಮಾಪನಾಂಕ ನಿರ್ಣಯವನ್ನು ಬಯಸುತ್ತವೆ.',
  'a191': 'ಇತಿಹಾಸಕಾರರು ನಿರ್ದಿಷ್ಟ ಯುಗದ ನಂತರ ರೈತ ಕಾರ್ಮಿಕರ ವ್ಯವಸ್ಥಿತ ಹಕ್ಕು ಕಸಿದುಕೊಳ್ಳುವಿಕೆಯನ್ನು ದಾಖಲಿಸಿದರು.',
  'a192': 'ಕ್ವಾಂಟಮ್ ಎಂಟ್ಯಾಂಗಲ್‌ಮೆಂಟ್ ನಕ್ಷತ್ರಗಳ ಅಂತರದಲ್ಲೂ ಕಣಗಳ ನಡುವಿನ ತತ್‌ಕ್ಷಣದ ವಿಚಿತ್ರ ಸಂಪರ್ಕವನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ.',
  'a193': 'ನೋವನ್ನು ಅನುಭವಿಸುವ ಸಾಮರ್ಥ್ಯವಿರುವ ಎಲ್ಲಾ ಜೀವಿಗಳಿಗೂ ನೈತಿಕ ಕಾಳಜಿಯನ್ನು ವಿಸ್ತರಿಸಬೇಕು ಎಂದು ನೈತಿಕತಜ್ಞರು ವಾದಿಸಿದರು.',
  'a194': 'ವಸಾಹತುಶಾಹಿ ನಂತರದ ಇತಿಹಾಸ ರಚನೆಯು ಸ್ಥಳೀಯ ನಾಗರಿಕತೆಗಳನ್ನು ಕಡೆಗಣಿಸಿದ ಯುರೋಪಿಯನ್ ನಿರೂಪಣೆಗಳನ್ನು ತಳ್ಳಿಹಾಕುತ್ತದೆ.',
  'a195': 'ಮಾರುಕಟ್ಟೆ ಪಾಲಿನ ಕುಸಿತವನ್ನು ಎದುರಿಸಲು ಮುಖ್ಯ ಕಾರ್ಯನಿರ್ವಾಹಕ ಅಧಿಕಾರಿಯು ಸಮಗ್ರ ಪುನಶ್ಚೇತನ ತಂತ್ರವನ್ನು ರೂಪಿಸಿದರು.',
  'a196': 'ಅರಿವಿನ ಮರುಮೌಲ್ಯಮಾಪನ ವ್ಯಾಯಾಮಗಳು ಆಘಾತಕಾರಿ ನೆನಪುಗಳ ಸಮಯದಲ್ಲಿ ಮೆದುಳಿನ ತೀವ್ರ ಆತಂಕದ ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತವೆ.',
  'a197': 'ತೀರ್ಪುಗಾರರ ಚರ್ಚೆಯ ಸಮಯದಲ್ಲಿ ನಡೆದ ಗಂಭೀರ ನಿಯಮ ಉಲ್ಲಂಘನೆಗಳನ್ನು ಉಲ್ಲೇಖಿಸಿ ಮೇಲ್ಮನವಿ ನ್ಯಾಯಾಲಯವು ಕೆಳ ನ್ಯಾಯಾಲಯದ ತೀರ್ಪನ್ನು ರದ್ದುಗೊಳಿಸಿತು.',
  'a198': 'ಪುರಾತತ್ತ್ವ ಶಾಸ್ತ್ರದ ಉತ್ಖನನಗಳು ಕಂಚಿನ ಯುಗದ ಪತನದ ಸಮಯದಲ್ಲಿ ಅಪೌಷ್ಟಿಕತೆಯ ಆಳವಾದ ಕುರುಹುಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸಿದವು.',
  'a199': 'ರಹಸ್ಯ ಪರಮಾಣು ಪ್ರಸರಣವನ್ನು ತಡೆಯಲು ಈ ಒಪ್ಪಂದವು ಕಟ್ಟುನಿಟ್ಟಾದ ಪರಿಶೀಲನಾ ಕ್ರಮಗಳನ್ನು ಸ್ಥಾಪಿಸುತ್ತದೆ.',
  'a200': 'ಮಾತೃಭಾಷೆಯ ವ್ಯಾಕರಣ ರಚನೆಯು ಪ್ರಪಂಚದ ಬಗ್ಗೆ ಮನುಷ್ಯನ ಪರಿಕಲ್ಪನಾ ಗ್ರಹಿಕೆಯನ್ನು ನಿರ್ಣಾಯಕವಾಗಿ ರೂಪಿಸುತ್ತದೆ ಎಂದು ಭಾಷಾ ಸಿದ್ಧಾಂತವು ಹೇಳುತ್ತದೆ.',
};
